CREATE TABLE `Credential` (`id` VARCHAR(191) NOT NULL, `role` ENUM('MANAGEMENT','SUPERVISOR') NOT NULL, `tokenHash` CHAR(64) NOT NULL, `version` INTEGER NOT NULL DEFAULT 1, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `rotatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `Credential_role_key`(`role`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Session` (`id` VARCHAR(191) NOT NULL, `sessionHash` CHAR(64) NOT NULL, `csrfHash` CHAR(64) NOT NULL, `role` ENUM('MANAGEMENT','SUPERVISOR') NOT NULL, `credentialId` VARCHAR(191) NOT NULL, `credentialVersion` INTEGER NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `expiresAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Session_sessionHash_key`(`sessionHash`), INDEX `Session_expiresAt_idx`(`expiresAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Assignment` (`id` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, `draftRevisionId` VARCHAR(191) NULL, `publishedRevisionId` VARCHAR(191) NULL, UNIQUE INDEX `Assignment_draftRevisionId_key`(`draftRevisionId`), UNIQUE INDEX `Assignment_publishedRevisionId_key`(`publishedRevisionId`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Revision` (`id` VARCHAR(191) NOT NULL, `assignmentId` VARCHAR(191) NOT NULL, `number` INTEGER NOT NULL, `state` ENUM('WORKING','PUBLISHED','RETIRED') NOT NULL DEFAULT 'WORKING', `title` VARCHAR(200) NOT NULL, `description` TEXT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, `publishedAt` DATETIME(3) NULL, UNIQUE INDEX `Revision_assignmentId_number_key`(`assignmentId`,`number`), INDEX `Revision_state_publishedAt_idx`(`state`,`publishedAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Attachment` (`id` VARCHAR(191) NOT NULL, `revisionId` VARCHAR(191) NOT NULL, `storageKey` VARCHAR(180) NOT NULL, `thumbnailKey` VARCHAR(180) NULL, `originalName` VARCHAR(255) NOT NULL, `mimeType` VARCHAR(80) NOT NULL, `sizeBytes` BIGINT NOT NULL, `sha256` CHAR(64) NOT NULL, `width` INTEGER NULL, `height` INTEGER NULL, `position` INTEGER NOT NULL, `uploadId` VARCHAR(100) NULL, `uploadedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `Attachment_revisionId_position_key`(`revisionId`,`position`), UNIQUE INDEX `Attachment_revisionId_uploadId_key`(`revisionId`,`uploadId`), INDEX `Attachment_storageKey_idx`(`storageKey`), INDEX `Attachment_thumbnailKey_idx`(`thumbnailKey`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Session` ADD CONSTRAINT `Session_credentialId_fkey` FOREIGN KEY (`credentialId`) REFERENCES `Credential`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Assignment` ADD CONSTRAINT `Assignment_draftRevisionId_fkey` FOREIGN KEY (`draftRevisionId`) REFERENCES `Revision`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `Assignment` ADD CONSTRAINT `Assignment_publishedRevisionId_fkey` FOREIGN KEY (`publishedRevisionId`) REFERENCES `Revision`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `Revision` ADD CONSTRAINT `Revision_assignmentId_fkey` FOREIGN KEY (`assignmentId`) REFERENCES `Assignment`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Attachment` ADD CONSTRAINT `Attachment_revisionId_fkey` FOREIGN KEY (`revisionId`) REFERENCES `Revision`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
